{
  "turns": [
    {
      "speaker": "A",
      "text": "やあ、元気？",
      "english": "Hey, how are you?",
      "intendedTargetIds": []
    },
    {
      "speaker": "B",
      "text": "うん、元気だよ。そっちは？",
      "english": "Yeah, I'm good. And you?",
      "intendedTargetIds": []
    },
    {
      "speaker": "A",
      "text": "元気だよ。昨日、どこか行きましたか？",
      "english": "I'm good. Did you go anywhere yesterday?",
      "intendedTargetIds": [
        81
      ]
    },
    {
      "speaker": "B",
      "text": "いいえ、行かなかったです。家でご飯を食べました。",
      "english": "No, I didn't go anywhere. I ate a meal at home.",
      "intendedTargetIds": []
    },
    {
      "speaker": "A",
      "text": "そっか。じゃあ、今日、また家に行こうか？",
      "english": "I see. Well then, shall we go to my place again today?",
      "intendedTargetIds": [
        80
      ]
    },
    {
      "speaker": "B",
      "text": "いいですね！",
      "english": "That sounds good!",
      "intendedTargetIds": []
    },
    {
      "speaker": "A",
      "text": "ごめん、ちょっと待っててくれる？",
      "english": "Sorry, could you wait a moment?",
      "intendedTargetIds": [
        87
      ]
    },
    {
      "speaker": "B",
      "text": "大丈夫ですよ。",
      "english": "It's okay.",
      "intendedTargetIds": []
    },
    {
      "speaker": "A",
      "text": "ありがとう。今日、何ができるかな？",
      "english": "Thanks. I wonder what we can do today?",
      "intendedTargetIds": [
        46
      ]
    }
  ],
  "sceneId": "LS1",
  "setting": "A street corner where two friends meet."
}

{
