      "pinyin": "Zuótiān, zài cì jiā qù ba xiǎng le yīxiē, dànshì.",
      "romaji": "Kinou, mata ie ni ikou ka to omotta n dakedo."
    },
    {
      "speaker": "B",
      "text": "いいけど、今は？",
      "english": "That sounds good, but now?",
      "romaji": "Ii kedo, ima wa?"
    },
    {
      "speaker": "A",
      "text": "ごめん、言い間違えた。今日、家に行こう。",
      "english": "Sorry, I misspoke. Let's go to my place today.",
      "intendedTargetIds": [
        87
      ],
      "pinyin": "Duìbùqǐ, shuōcuò le. Jīntiān, qù jiā.",
      "romaji": "Gomen, iimachigaeta. Kyou, ie ni ikou."
    },
    {
      "speaker": "B",
      "text": "大丈夫。行こう。",
      "english": "It's okay. Let's go.",
      "intendedTargetIds": [
        46
      ],
      "pinyin": "Méishì. Qù ba.",
      "romaji": "Daijoubu. Ikou."
    }
  ],
  "sceneId": "LS1",
  "setting": "A park bench"
}

